        PropertyMetadata(name='educational_level', schema_name='educationalLevel', schema_url='https://schema.org/educationalLevel', ranges=('DefinedTerm', 'Text', 'URL'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('CreativeWork', 'EducationEvent', 'EducationalOccupationalCredential', 'LearningResource'), external_domains=(), comment="The level in terms of progression through an educational or training context. Examples of educational levels include 'beginner', 'intermediate' or 'advanced', and formal sets of level indicators.", label='educationalLevel', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/1779',)),
