        PropertyMetadata(name='expires', schema_name='expires', schema_url='https://schema.org/expires', ranges=('Date', 'DateTime'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('Certification', 'CreativeWork'), external_domains=(), comment='Date the content expires and is no longer useful or available. For example a [[VideoObject]] or [[NewsArticle]] whose availability or relevance is time-limited, a [[ClaimReview]] fact check whose publisher wants to indicate that it may no longer be relevant (or helpful to highlight) after some date, or a [[Certification]] the validity has expired.', label='expires', contributors=(), sources=()),
        PropertyMetadata(name='file_format', schema_name='fileFormat', schema_url='https://schema.org/fileFormat', ranges=('Text', 'URL'), external_ranges=(), inverse_of=None, superseded_by='encodingFormat', supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('CreativeWork',), external_domains=(), comment="Media type, typically MIME format (see [IANA site](http://www.iana.org/assignments/media-types/media-types.xhtml)) of the content, e.g. application/zip of a SoftwareApplication binary. In cases where a CreativeWork has several media type representations, 'encoding' can be used to indicate each MediaObject alongside particular fileFormat information. Unregistered or niche file formats can be indicated instead via the most appropriate URL, e.g. defining Web page or a Wikipedia entry.", label='fileFormat', contributors=(), sources=()),
