        PropertyMetadata(name='in_language', schema_name='inLanguage', schema_url='https://schema.org/inLanguage', ranges=('Language', 'Text'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=('language',), equivalent_properties=('http://purl.org/dc/terms/language',), subproperty_of=(), domains=('BroadcastService', 'CommunicateAction', 'CreativeWork', 'Event', 'LinkRole', 'PronounceableText', 'WriteAction'), external_domains=(), comment='The language of the content or performance or used in an action. Please use one of the language codes from the [IETF BCP 47 standard](http://tools.ietf.org/html/bcp47). See also [[availableLanguage]].', label='inLanguage', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/2382',)),
        PropertyMetadata(name='interaction_statistic', schema_name='interactionStatistic', schema_url='https://schema.org/interactionStatistic', ranges=('InteractionCounter',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=('interactionCount',), equivalent_properties=(), subproperty_of=(), domains=('CreativeWork', 'Organization', 'Person'), external_domains=(), comment='The number of interactions for the CreativeWork using the WebSite or SoftwareApplication. The most specific child type of InteractionCounter should be used.', label='interactionStatistic', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/2421',)),
