        PropertyMetadata(name='learning_resource_type', schema_name='learningResourceType', schema_url='https://schema.org/learningResourceType', ranges=('DefinedTerm', 'Text'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('CreativeWork', 'LearningResource'), external_domains=(), comment="The predominant type or kind characterizing the learning resource. For example, 'presentation', 'handout'.", label='learningResourceType', contributors=(), sources=()),
