        PropertyMetadata(name='sd_license', schema_name='sdLicense', schema_url='https://schema.org/sdLicense', ranges=('CreativeWork', 'URL'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('CreativeWork',), external_domains=(), comment='A license document that applies to this structured data, typically indicated by URL.', label='sdLicense', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/1886',)),
        PropertyMetadata(name='sd_publisher', schema_name='sdPublisher', schema_url='https://schema.org/sdPublisher', ranges=('Organization', 'Person'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('CreativeWork',), external_domains=(), comment='Indicates the party responsible for generating and publishing the current structured data markup, typically in cases where the structured data is derived automatically from existing published content but published on a different site. For example, student projects and open data initiatives often re-publish existing content with more explicitly structured metadata. The\n[[sdPublisher]] property helps make such practices more explicit.', label='sdPublisher', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/1886',)),
        PropertyMetadata(name='size', schema_name='size', schema_url='https://schema.org/size', ranges=('DefinedTerm', 'QuantitativeValue', 'SizeSpecification', 'Text'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=('http://unece.org/vocab#sizeDescription',), subproperty_of=(), domains=('CreativeWork', 'Product'), external_domains=(), comment="A standardized size of a product or creative work, specified either through a simple textual string (for example 'XL', '32Wx34L'), a  QuantitativeValue with a unitCode, or a comprehensive and structured [[SizeSpecification]]; in other cases, the [[width]], [[height]], [[depth]] and [[weight]] properties may be more applicable. ", label='size', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/1797',)),
