        PropertyMetadata(name='teaches', schema_name='teaches', schema_url='https://schema.org/teaches', ranges=('DefinedTerm', 'Text'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('CreativeWork', 'EducationEvent', 'LearningResource'), external_domains=(), comment='The item being described is intended to help a person learn the competency or learning outcome defined by the referenced term.', label='teaches', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/2427',)),
